SELECT DISTINCT b.name
FROM battle b
WHERE b.bulgarian_commander = 'Kaloyan' AND b.latin_commander = 'Baldwin I';

SELECT AVG(LifeExpectancy) 
FROM country 
WHERE Region = 'Central Africa';

SELECT COUNT(*) 
FROM TV_Channel 
WHERE Language = 'English';

SELECT Record_Company, Year_of_Founded
FROM orchestra
ORDER BY Year_of_Founded DESC;

SELECT Name, Song_release_year
FROM singer
WHERE Age = (SELECT MIN(Age) FROM singer);

SELECT conductor.Name 
FROM conductor 
ORDER BY conductor.Age;

SELECT COUNT(*) 
FROM cars_data 
WHERE Accelerate > (SELECT MAX(Horsepower) FROM cars_data);

SELECT COUNT(*) 
FROM Owners 
WHERE owner_id NOT IN (SELECT owner_id FROM Dogs WHERE abandoned_yn = 'Y');

SELECT Template_Type_Code 
FROM Ref_Template_Types 
WHERE Template_Type_Description = 'Book';

SELECT shop.Manager_name, shop.District
FROM shop
WHERE shop.Number_products = (
    SELECT MAX(Number_products)
    FROM shop
);

SELECT Name 
FROM conductor 
WHERE Nationality <> 'USA';

SELECT first_name, last_name
FROM Professionals
WHERE professional_id IN (
    SELECT professional_id
    FROM Treatments
    WHERE cost_of_treatment < (
        SELECT AVG(cost_of_treatment)
        FROM Treatments
    )
);

SELECT Name 
FROM teacher 
WHERE Hometown != 'Little Lever Urban District';

SELECT StuID, COUNT(PetID) as Number_of_Pets
FROM Has_Pet
GROUP BY StuID;

SELECT Record_Company, COUNT(*) as Number_of_Orchestras
FROM orchestra
GROUP BY Record_Company;

SELECT COUNT(*) 
FROM airlines 
WHERE Country = 'USA';

SELECT PetType, AVG(pet_age) as Average_Age, MAX(pet_age) as Maximum_Age
FROM Pets
GROUP BY PetType;

SELECT Name, Population, HeadOfState
FROM country
WHERE SurfaceArea = (SELECT MAX(SurfaceArea) FROM country);

SELECT COUNT(*) 
FROM Highschooler 
WHERE grade = 9 OR grade = 10;

SELECT COUNT(*) FROM flights
WHERE Airline = (
    SELECT uid FROM airlines WHERE Airline = 'Jetblue Airways'
);

SELECT Name, Location, District, Number_products 
FROM shop 
ORDER BY Number_products DESC;

SELECT Citizenship, COUNT(*) as Number_of_Singers
FROM singer
GROUP BY Citizenship;
